import {json} from './data.js';
import {esc,icon} from './ui.js';
import {learners} from './store.js';
let unlocked=false,selected=null;
const unlockKey='parola.access.session.v1',learnerKey='parola.learner.session.v1';
function get(key){try{return sessionStorage.getItem(key);}catch{return null;}}
function set(key,value){try{if(value===null)sessionStorage.removeItem(key);else sessionStorage.setItem(key,value);}catch{}}
export async function passwordMatches(password,config){if(!globalThis.crypto?.subtle)throw Error('Open the app on HTTPS or localhost to enter the shared password.');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`${config.salt}:${password}`));return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')===config.passwordHash;}
function intro(title,description,body){return `<main id="main" class="access-page" tabindex="-1"><section class="access-card"><a class="access-brand" href="#">${icon('leaf')} parola</a><span class="eyebrow">A LITTLE PRACTICE. A BIGGER WORLD.</span><h1>${title}</h1><p class="muted">${description}</p>${body}</section><p class="access-footer">Your own pace. Your own language garden.</p></main>`;}
export async function ensureAccess(root,onReady){const config=await json('data/access.json');unlocked=unlocked||get(unlockKey)===config.passwordHash;selected=selected||get(learnerKey);if(unlocked&&learners.some(x=>x.id===selected))return selected;
 if(!unlocked){document.title='Welcome · Parola';root.innerHTML=intro('A little space, just for us.','Enter the shared password to open your language garden.',`<form id="access-form"><label class="field" for="access-password">Password<div class="password-field"><input id="access-password" type="password" autocomplete="current-password" required aria-describedby="access-error"><button id="show-password" type="button" aria-label="Show password" aria-pressed="false">Show</button></div></label><p id="access-error" class="access-error" role="alert"></p><button class="button access-submit" type="submit">Enter our garden ${icon('arrow')}</button></form>`);const input=root.querySelector('#access-password');root.querySelector('#show-password').onclick=e=>{const show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-label',show?'Hide password':'Show password');e.currentTarget.setAttribute('aria-pressed',String(show));};root.querySelector('#access-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]'),error=root.querySelector('#access-error');button.disabled=true;try{const valid=await passwordMatches(input.value,config);if(!valid){error.textContent='That password isn’t quite right. Please try again.';input.setAttribute('aria-invalid','true');input.focus();input.select();return;}unlocked=true;set(unlockKey,config.passwordHash);set(learnerKey,null);selected=null;await onReady();}catch(err){error.textContent=err.message;}finally{if(button.isConnected)button.disabled=false;}};input.focus();return null;}
 document.title='Who is learning today? · Parola';root.innerHTML=intro('Who is learning today?','Choose your name. We’ll pick up where you left off.',`<div class="learner-options">${learners.map(profile=>`<button class="learner-card" data-learner="${profile.id}"><span class="learner-avatar ${profile.id}">${profile.name[0]}</span><strong>${esc(profile.name)}</strong><span>${profile.language==='ar'?'العربية · Arabic':'Italiano · Italian'}</span><small>Your progress, saved separately</small>${icon('arrow')}</button>`).join('')}</div><button class="button ghost" id="back-to-lock">Back to password</button>`);for(const button of root.querySelectorAll('[data-learner]'))button.onclick=()=>{selected=button.dataset.learner;set(learnerKey,selected);onReady();};root.querySelector('#back-to-lock').onclick=()=>{lock();onReady();};root.querySelector('[data-learner]').focus();return null;}
export function chooseAgain(){selected=null;set(learnerKey,null);}
export function lock(){unlocked=false;selected=null;set(unlockKey,null);set(learnerKey,null);}
